style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
:root {
    --jojo-purple: #5c1a7f;
    --jojo-gold: #ffcc4d;
    --jojo-black: #060606;
  }

  body {
    background:
      radial-gradient(circle at 10% 0%, rgba(255, 204, 77, 0.04) 0%, rgba(0,0,0,0) 40%),
      radial-gradient(circle at 90% 100%, rgba(255, 92, 240, 0.08) 0%, rgba(0,0,0,0) 50%),
      linear-gradient(135deg, #0b0a0f 0%, #000 100%);
    color: #fefafc !important;
    font-family: "Segoe UI", "Trebuchet MS", sans-serif !important;
    letter-spacing: .03em;
    position: relative;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image:
      linear-gradient(135deg, rgba(255, 204, 77, 0.07) 15%, rgba(0,0,0,0) 15%),
      linear-gradient(315deg, rgba(92, 26, 127, 0.05) 15%, rgba(0,0,0,0) 15%);
    background-size: 120px 120px, 150px 150px;
    mix-blend-mode: screen;
    opacity: .6;
    z-index: 1;
    pointer-events: none;
    animation: jojogrid 18s linear infinite;
  }

  @keyframes jojogrid {
    from { background-position: 0 0, 0 0; }
    to { background-position: 300px 300px, -200px -200px; }
  }

  body::after {
    content: "JOJO • josue remix • JOJO • josue remix • JOJO • josue remix • JOJO • josue remix";
    position: fixed;
    top: 14%;
    left: -6%;
    font-size: 5.2rem;
    font-weight: 900;
    transform: rotate(-14deg);
    color: rgba(255, 204, 77, 0.025);
    text-shadow:
      0 0 10px rgba(255, 92, 240, 0.03),
      0 0 32px rgba(255, 92, 240, 0.02);
    pointer-events: none;
    z-index: 2;
    letter-spacing: .12em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  div, section, article, main, header, footer, nav {
    background: rgba(2, 2, 2, 0.38) !important;
    border: 1px solid rgba(255, 204, 77, 0.12);
    border-radius: 16px;
    backdrop-filter: blur(4px);
  }

  h1, h2, h3 {
    color: var(--jojo-gold) !important;
    text-transform: uppercase;
    letter-spacing: .2em;
    text-shadow:
      0 0 6px rgba(255, 204, 77, 0.6),
      0 0 14px rgba(92, 26, 127, .5);
  }

  a {
    color: var(--jojo-gold) !important;
    text-decoration: none !important;
    transition: .15s ease-out;
  }
  a:hover {
    color: #ff5cf0 !important;
    text-shadow: 0 0 8px rgba(255, 92, 240, .8);
    transform: skewX(-4deg);
  }

  button,
  input[type="button"],
  input[type="submit"],
  .btn,
  [role="button"] {
    background: radial-gradient(circle, #ffcc4d 0%, #5c1a7f 80%);
    color: #000 !important;
    border: 2px solid #ffcc4d;
    border-radius: 999px;
    padding: 6px 18px !important;
    font-weight: 700;
    text-transform: uppercase;
    box-shadow: 0 0 12px rgba(255, 204, 77, .4);
  }
  button:hover,
  input[type="button"]:hover,
  input[type="submit"]:hover,
  .btn:hover,
  [role="button"]:hover {
    transform: translateY(-1px) scale(1.02);
    box-shadow: 0 0 18px rgba(255, 204, 77, .7);
  }

  input[type="text"],
  input[type="email"],
  input[type="password"],
  textarea,
  select {
    background: rgba(0,0,0,0.45) !important;
    border: 1px solid rgba(255, 204, 77, 0.3) !important;
    color: #fff !important;
    border-radius: 10px !important;
  }
  input:focus,
  textarea:focus,
  select:focus {
    outline: none !important;
    box-shadow: 0 0 8px rgba(255, 92, 240, 0.5);
  }

  .jojos-vibe {
    position: fixed;
    bottom: 12%;
    right: 6%;
    font-weight: 900;
    font-size: 3.6rem;
    color: rgba(255, 92, 240, .32);
    text-shadow: 0 0 14px rgba(255, 92, 240, .4);
    pointer-events: none;
    text-transform: uppercase;
    letter-spacing: .08em;
    z-index: 5;
    animation: jojobounce 5s ease-in-out infinite;
  }
  .jojos-vibe::after {
    content: "josue remix";
    display: block;
    font-size: 1.1rem;
    letter-spacing: .3em;
    color: rgba(255, 204, 77, .75);
  }

  @keyframes jojobounce {
    0%,100% { transform: translateY(0); opacity: .8; }
    50% { transform: translateY(-18px); opacity: 1; }
  }

  ::selection {
    background: rgba(255, 92, 240, .9);
    color: #000;
  }

  ::-webkit-scrollbar {
    width: 12px;
  }
  ::-webkit-scrollbar-track {
    background: rgba(0,0,0,0.2);
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #ffcc4d 0%, #5c1a7f 100%);
    border-radius: 999px;
    border: 2px solid #000;
  }
}
